DECLARE @Esperados INT = 49;
DECLARE @Metodo NVARCHAR(80) = N'cruce_catalogo_red_v1';
DECLARE @Usuario NVARCHAR(300) = N'Codex · autorizado por usuario · 2026-08-02';

BEGIN TRY
    BEGIN TRANSACTION;

    IF ISJSON(@Payload) <> 1
        THROW 51000, N'El payload territorial no es JSON válido.', 1;

    CREATE TABLE #Entrada
    (
        ProyectoId BIGINT NOT NULL,
        PEM NVARCHAR(500) NULL,
        Etiqueta NVARCHAR(300) NOT NULL,
        TipoElemento NVARCHAR(100) NOT NULL,
        ClaveElementoRed NVARCHAR(200) NOT NULL,
        TipoGeometria NVARCHAR(30) NOT NULL,
        GeometriaJson NVARCHAR(MAX) NOT NULL,
        Latitud DECIMAL(9,6) NULL,
        Longitud DECIMAL(10,6) NULL,
        PrecisionUbicacion NVARCHAR(40) NOT NULL,
        MetodoUbicacion NVARCHAR(80) NOT NULL,
        Fuente NVARCHAR(500) NOT NULL,
        FechaCorte DATE NULL,
        RadioSugeridoKm DECIMAL(8,2) NULL,
        Puntaje INT NOT NULL,
        NivelConfianza NVARCHAR(30) NOT NULL,
        FuenteDocumento NVARCHAR(1000) NULL,
        EstadoValidacion NVARCHAR(100) NOT NULL
    );

    INSERT #Entrada
    SELECT
        ProyectoId, PEM, Etiqueta, TipoElemento, ClaveElementoRed,
        TipoGeometria, GeometriaJson, Latitud, Longitud,
        PrecisionUbicacion, MetodoUbicacion, Fuente, FechaCorte,
        RadioSugeridoKm, Puntaje, NivelConfianza, FuenteDocumento,
        EstadoValidacion
    FROM OPENJSON(@Payload)
    WITH
    (
        ProyectoId BIGINT '$.ProyectoId',
        PEM NVARCHAR(500) '$.PEM',
        Etiqueta NVARCHAR(300) '$.Etiqueta',
        TipoElemento NVARCHAR(100) '$.TipoElemento',
        ClaveElementoRed NVARCHAR(200) '$.ClaveElementoRed',
        TipoGeometria NVARCHAR(30) '$.TipoGeometria',
        GeometriaJson NVARCHAR(MAX) '$.Geometria' AS JSON,
        Latitud DECIMAL(9,6) '$.Latitud',
        Longitud DECIMAL(10,6) '$.Longitud',
        PrecisionUbicacion NVARCHAR(40) '$.PrecisionUbicacion',
        MetodoUbicacion NVARCHAR(80) '$.MetodoUbicacion',
        Fuente NVARCHAR(500) '$.Fuente',
        FechaCorte DATE '$.FechaCorte',
        RadioSugeridoKm DECIMAL(8,2) '$.RadioSugeridoKm',
        Puntaje INT '$.Puntaje',
        NivelConfianza NVARCHAR(30) '$.NivelConfianza',
        FuenteDocumento NVARCHAR(1000) '$.FuenteDocumento',
        EstadoValidacion NVARCHAR(100) '$.EstadoValidacion'
    );

    IF (SELECT COUNT(*) FROM #Entrada) <> @Esperados
        THROW 51001, N'Preflight: el lote no contiene exactamente 49 ubicaciones.', 1;
    IF (SELECT COUNT(DISTINCT ProyectoId) FROM #Entrada) <> @Esperados
        THROW 51002, N'Preflight: existen ProyectoId repetidos.', 1;
    IF EXISTS
    (
        SELECT 1 FROM #Entrada
        WHERE TipoGeometria NOT IN (N'Point',N'MultiPoint',N'LineString',N'MultiLineString',N'Polygon',N'MultiPolygon')
           OR PrecisionUbicacion <> N'geocodificada'
           OR MetodoUbicacion <> @Metodo
           OR NivelConfianza <> N'alta'
           OR Puntaje < 90
           OR ISJSON(GeometriaJson) <> 1
           OR Latitud NOT BETWEEN 14 AND 33.5
           OR Longitud NOT BETWEEN -118 AND -86
    )
        THROW 51003, N'Preflight: geometría, coordenadas o evidencia inválida.', 1;
    IF EXISTS
    (
        SELECT 1
        FROM #Entrada e
        LEFT JOIN dgmesnie.vw_PAMProyectoVigente p
          ON p.ProyectoId = e.ProyectoId
         AND p.EstadoVigenciaCartera = N'Vigente'
        WHERE p.ProyectoId IS NULL
    )
        THROW 51004, N'Preflight: uno o más proyectos ya no están vigentes.', 1;

    DECLARE @RedVersionId BIGINT =
        (SELECT TOP (1) VersionId FROM dgmesnie.RedElectricaVersion WHERE Activa = 1 ORDER BY VersionId DESC);
    IF @RedVersionId IS NULL
        THROW 51005, N'Preflight: no existe una versión activa del grafo eléctrico.', 1;
    IF EXISTS
    (
        SELECT 1
        FROM #Entrada e
        WHERE
            (e.TipoElemento = N'subestacion' AND NOT EXISTS
                (SELECT 1 FROM dgmesnie.RedElectricaNodo n
                 WHERE n.VersionId = @RedVersionId
                   AND n.NodoClave = e.ClaveElementoRed
                   AND n.EsVirtual = 0))
         OR (e.TipoElemento = N'linea_transmision' AND NOT EXISTS
                (SELECT 1 FROM dgmesnie.RedElectricaArista a
                 WHERE a.VersionId = @RedVersionId
                   AND a.ClaveElementoCatalogo = e.ClaveElementoRed
                   AND NULLIF(LTRIM(RTRIM(a.GeometriaJson)), N'') IS NOT NULL))
    )
        THROW 51006, N'Preflight: un elemento no existe en el grafo activo o no tiene geometría.', 1;

    IF EXISTS
    (
        SELECT 1
        FROM #Entrada e
        JOIN dgmesnie.PAMProyectoUbicacion u WITH (UPDLOCK, HOLDLOCK)
          ON u.ProyectoId = e.ProyectoId
         AND u.Activa = 1
    )
        THROW 51007, N'Preflight: un proyecto del lote ya tiene una ubicación activa.', 1;

    DECLARE @Insertadas TABLE
    (
        UbicacionId BIGINT,
        ProyectoId BIGINT,
        Etiqueta NVARCHAR(300),
        TipoGeometria NVARCHAR(30),
        Validada BIT,
        Activa BIT
    );

    INSERT dgmesnie.PAMProyectoUbicacion
    (
        ProyectoId, Etiqueta, TipoGeometria, GeometriaJson,
        Latitud, Longitud, PrecisionUbicacion, MetodoUbicacion,
        Fuente, FechaCorte, RadioSugeridoKm, Orden, EsPrincipal,
        Validada, Activa, UsuarioRegistro, Observaciones
    )
    OUTPUT inserted.UbicacionId, inserted.ProyectoId, inserted.Etiqueta,
           inserted.TipoGeometria, inserted.Validada, inserted.Activa
      INTO @Insertadas
    SELECT
        e.ProyectoId, e.Etiqueta, e.TipoGeometria, e.GeometriaJson,
        e.Latitud, e.Longitud, e.PrecisionUbicacion, e.MetodoUbicacion,
        e.Fuente, e.FechaCorte, e.RadioSugeridoKm, 1, 1,
        0, 1, @Usuario,
        LEFT(CONCAT(
            N'Asociación sugerida no validada. ClaveElementoRed=', e.ClaveElementoRed,
            N'; Puntaje=', e.Puntaje,
            N'; Confianza=', e.NivelConfianza,
            N'; FuenteDocumento=', COALESCE(e.FuenteDocumento, N''),
            N'; Lote=PAM-UBICACION-20260802-01.'), 1000)
    FROM #Entrada e;

    IF (SELECT COUNT(*) FROM @Insertadas) <> @Esperados
        THROW 51008, N'Aplicación: no se insertaron exactamente 49 ubicaciones.', 1;

    COMMIT TRANSACTION;

    SELECT COUNT(*) AS Insertadas,
           SUM(CASE WHEN Validada = 0 AND Activa = 1 THEN 1 ELSE 0 END) AS ActivasNoValidadas
    FROM @Insertadas;
    SELECT * FROM @Insertadas ORDER BY ProyectoId;
END TRY
BEGIN CATCH
    IF @@TRANCOUNT > 0 ROLLBACK TRANSACTION;
    THROW;
END CATCH;
